WITH with_latest AS (SELECT s.*, x.order_shipping_fee FROM stores s JOIN LATERAL (SELECT c.shipping_fee AS order_shipping_fee FROM orders c WHERE c.store_id = s.id ORDER BY c.discount DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT region, SIZE(COLLECT_SET(region)) AS num_regions, PERCENTILE_APPROX(sqft, 0.95) AS sqft_p95, PERCENTILE_APPROX(sqft, ARRAY(0.25, 0.5, 0.75)) AS sqft_quartiles, MAX(order_shipping_fee) AS max_order_shipping_fee, MAX(sqft) FILTER (WHERE city = 'Singapore') AS singapore_max_sqft FROM with_latest GROUP BY region ORDER BY max_order_shipping_fee NULLS LAST
